package com.yonlab.vision;
import android.content.Context;import android.graphics.*;import org.tensorflow.lite.*;import org.json.*;import java.nio.*;import java.io.*;import java.util.*;
/** The Apache-2.0 Pascal21 MobileNet/DeepLab graph, not an instance counter. */
final class OneDeepLabEngine implements AutoCloseable {
 private final Interpreter engine;final String sha256;private boolean closed;private static final int SIDE=257;
 private static final String[] LABELS={"배경","비행기","자전거","새","보트","병","버스","자동차","고양이","의자","소","식탁","개","말","오토바이","사람","화분","양","소파","기차","모니터"};
 OneDeepLabEngine(Context c)throws Exception{OneLiteAsset asset=new OneLiteAsset(c,"deeplab-v3.tflite");sha256=asset.sha256;int threads=OneExecutionSettings.threads(c);Interpreter model=new Interpreter(asset.bytes,new Interpreter.Options().setNumThreads(threads));try{model.allocateTensors();if(!Arrays.equals(model.getInputTensor(0).shape(),new int[]{1,SIDE,SIDE,3})||model.getInputTensor(0).dataType()!=DataType.FLOAT32||!Arrays.equals(model.getOutputTensor(0).shape(),new int[]{1,SIDE,SIDE,21}))throw new IOException("영역 모델 입출력을 확인하세요");engine=model;}catch(Exception|Error e){model.close();throw e;}}
 synchronized void segment(Bitmap image,OneModelRunner.Cancel cancel,OneModelRunner.Result r)throws Exception{
  if(closed||cancel.canceled())throw new InterruptedIOException("canceled");Bitmap scaled=Bitmap.createScaledBitmap(image,SIDE,SIDE,true);int[] pixels=new int[SIDE*SIDE];scaled.getPixels(pixels,0,SIDE,0,0,SIDE,SIDE);if(scaled!=image)scaled.recycle();ByteBuffer input=ByteBuffer.allocateDirect(pixels.length*3*4).order(ByteOrder.nativeOrder());for(int p:pixels)for(int shift:new int[]{16,8,0})input.putFloat((((p>>>shift)&255)-127.5f)/127.5f);input.rewind();ByteBuffer output=ByteBuffer.allocateDirect(SIDE*SIDE*21*4).order(ByteOrder.nativeOrder());engine.run(input,output);output.rewind();int[] mask=new int[SIDE*SIDE],counts=new int[21];for(int i=0;i<mask.length;i++){if((i&1023)==0&&cancel.canceled())throw new InterruptedIOException("canceled");int best=0;float maximum=-Float.MAX_VALUE;for(int k=0;k<21;k++){float value=output.getFloat();if(!Float.isFinite(value))throw new IOException("영역 출력이 유효하지 않습니다");if(value>maximum){maximum=value;best=k;}}mask[i]=best;counts[best]++;}
  int w=image.getWidth(),h=image.getHeight();int[] overlay=new int[w*h],colors=new int[21];for(int i=1;i<21;i++)colors[i]=0x78000000|(Color.HSVToColor(new float[]{(i*47)%360,.78f,.96f})&0xffffff);long foreground=0;for(int y=0;y<h;y++){if((y&63)==0&&cancel.canceled())throw new InterruptedIOException("canceled");for(int x=0;x<w;x++){int cls=mask[Math.min(SIDE-1,y*SIDE/h)*SIDE+Math.min(SIDE-1,x*SIDE/w)];overlay[y*w+x]=colors[cls];if(cls!=0)foreground++;}}
  r.image=image.copy(Bitmap.Config.ARGB_8888,true);Bitmap tint=Bitmap.createBitmap(overlay,w,h,Bitmap.Config.ARGB_8888);try{new Canvas(r.image).drawBitmap(tint,0,0,null);}finally{tint.recycle();}List<Integer> order=new ArrayList<>();for(int i=1;i<21;i++)if(counts[i]>0)order.add(i);order.sort((a,b)->Integer.compare(counts[b],counts[a]));JSONArray classes=new JSONArray();StringBuilder detail=new StringBuilder();for(int cls:order){double fraction=counts[cls]/(double)(SIDE*SIDE);classes.put(new JSONObject().put("classId",cls).put("label",LABELS[cls]).put("maskPixels",counts[cls]).put("fraction",fraction));if(detail.length()<600)detail.append(LABELS[cls]).append("  ").append(String.format(Locale.KOREA,"%.1f%%",fraction*100)).append('\n');}r.metrics.put("classes",classes).put("foregroundPixels",foreground).put("totalPixels",(long)w*h).put("maskWidth",SIDE).put("maskHeight",SIDE).put("classCount",21).put("normalizationMean",127.5).put("normalizationStd",127.5).put("pipeline","RGB resize257 → DeepLab21 logits argmax → original-size semantic overlay");r.summary="영역 종류 "+order.size()+"개 · "+String.format(Locale.KOREA,"%.1f%%",100d*foreground/(w*h));r.detail=detail.toString();
 }
 public synchronized void close(){if(!closed){closed=true;engine.close();}}
}
